draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Socrates
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2, H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 60);
  ctx.lineTo(W/2 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 60);
  ctx.lineTo(W/2 + 20, H/2 + 80);
  ctx.stroke();

  // Question mark
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 - 20 + 20*Math.sin(t));
  ctx.lineTo(W/2 + 50, H/2 + 20 + 20*Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 40 + 20*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.stroke();

  // Thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 80, H/2 - 20, 30 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('What is truth?', W/2 + 80, H/2 - 20);

  ctx.restore();
}
